old='''<section class="view" id="view-config"><div class="config"><div class="card" style="padding:14px"><h2>AI Configuration</h2><div class="field"><label>Provider</label><select id="provider"><option value="openrouter">OpenRouter</option><option value="venice">Venice.ai</option><option value="anthropic">Anthropic</option></select></div><div class="field"><label>Model</label><input id="model"></div><div class="field"><label>API key</label><input id="apiKey" type="password"></div><button class="btn" id="saveConfig">Save</button><button class="btn" id="verifyConfig">Verify</button><span id="cfgStatus" class="cfgStatus"></span></div></div></section>'''
new='''<section class="view" id="view-config"><div class="config"><div class="card" style="padding:14px"><h2>AI Configuration</h2><div class="field"><label>Default provider</label><select id="defaultProvider"><option value="venice">Venice.ai</option><option value="openrouter">OpenRouter</option><option value="anthropic">Anthropic direct</option></select></div><div class="providerCard"><h3>Venice.ai <span class="cfgStatus" id="veniceStatus"></span></h3><div class="field"><label>API key</label><input id="veniceKey" type="password" autocomplete="new-password" spellcheck="false" autocapitalize="off"></div><div class="field"><label>Model</label><select id="veniceModel"><option value="">— load models first —</option></select></div><div class="actions left"><button class="btn" id="veniceLoad">Load models</button><button class="btn" id="veniceValidate">Validate & save</button></div></div><div class="providerCard"><h3>OpenRouter <span class="cfgStatus" id="openrouterStatus"></span></h3><div class="field"><label>API key</label><input id="openrouterKey" type="password" autocomplete="new-password" spellcheck="false" autocapitalize="off" placeholder="sk-or-…"></div><div class="field"><label>Model</label><select id="openrouterModel"><option value="">— load models first —</option></select></div><div class="actions left"><button class="btn" id="openrouterLoad">Load models</button><button class="btn" id="openrouterValidate">Validate & save</button></div></div><div class="providerCard"><h3>Anthropic direct <span class="cfgStatus" id="anthropicStatus"></span></h3><div class="field"><label>API key</label><input id="anthropicKey" type="password" autocomplete="new-password" spellcheck="false" autocapitalize="off" placeholder="sk-ant-…"></div><div class="field"><label>Model</label><input id="anthropicModel" placeholder="claude-sonnet-4-5"></div><div class="actions left"><button class="btn" id="anthropicValidate">Validate & save</button></div></div><div class="cfgNote" id="cfgSummary"></div></div></div></section>'''
