s=s.replace(old,new)
s=s.replace('.cfgStatus{margin-left:8px;color:var(--muted);font-size:10px}', '.cfgStatus{margin-left:8px;color:var(--muted);font-size:10px}.providerCard{margin-top:10px;padding:10px;border:1px solid var(--line);border-radius:9px;background:#081522}.providerCard h3{margin:0 0 8px}.actions.left{justify-content:flex-start}.cfgNote{margin-top:10px;color:var(--muted);font-size:10px}.cfgStatus.good{color:var(--good)}.cfgStatus.bad{color:var(--bad)}')

start=s.index("function analyses(){")
end=s.index("function analysisState(){", start)
prefix=s[:start]
suffix=s[end:]
replacement=r'''function analyses(){try{return JSON.parse(localStorage.getItem(K)||'[]')}catch{return[]}}function saveAnalyses(a){localStorage.setItem(K,JSON.stringify(a))}
const AIK='marketNavigatorAIRegistryV1';function aiRegistry(){try{return JSON.parse(localStorage.getItem(AIK)||'{}')}catch{return{}}}function saveAIRegistry(r){localStorage.setItem(AIK,JSON.stringify(r))}function providerRec(p){let r=aiRegistry();return(r.providers||{})[p]||{}}function providerName(p){return p==='venice'?'Venice.ai':p==='openrouter'?'OpenRouter':'Anthropic direct'}function fillModelSelect(id,models,current){let el=$(id);el.innerHTML='';if(!models.length){el.innerHTML='<option value="">— no models —</option>';return}for(let m of models){let o=document.createElement('option');o.value=m;o.textContent=m;el.appendChild(o)}if(current&&models.includes(current))el.value=current}function setPStatus(p,text,ok=null){let el=$(p+'Status');el.textContent=text;el.classList.toggle('good',ok===true);el.classList.toggle('bad',ok===false)}function renderAIConfig(){let r=aiRegistry(),ps=r.providers||{};$('defaultProvider').value=r.defaultProvider||'venice';for(let p of ['venice','openrouter','anthropic']){let q=ps[p]||{};$(p+'Key').value=q.key||'';if(p==='anthropic')$('anthropicModel').value=q.model||'';else fillModelSelect(p+'Model',q.models||([q.model].filter(Boolean)),q.model);setPStatus(p,q.verified?`registered · ${q.model}`:(q.key?'saved · validation required':'not registered'),q.verified?true:null)}$('cfgSummary').textContent=`Default: ${providerName($('defaultProvider').value)}. Keys stay in this browser's local storage.`}function providerEndpoints(p){if(p==='venice')return{models:'https://api.venice.ai/api/v1/models',chat:'https://api.venice.ai/api/v1/chat/completions'};if(p==='openrouter')return{models:'https://openrouter.ai/api/v1/models',chat:'https://openrouter.ai/api/v1/chat/completions'};return{chat:'https://api.anthropic.com/v1/messages'}}async function loadProviderModels(p){let key=$(p+'Key').value.trim();if(!key){setPStatus(p,'enter key first',false);return}setPStatus(p,'loading models…');try{let ep=providerEndpoints(p),r=await fetch(ep.models,{cache:'no-store',headers:{Authorization:`Bearer ${key}`}}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let ids=(x.data||x.models||[]).map(m=>typeof m==='string'?m:(m.id||m.model)).filter(Boolean).sort();if(!ids.length)throw Error('no models returned');fillModelSelect(p+'Model',ids,providerRec(p).model);let reg=aiRegistry(),providers=reg.providers||{};providers[p]={...(providers[p]||{}),key,models:ids,verified:false};saveAIRegistry({...reg,providers});setPStatus(p,`${ids.length} models loaded · choose one`,null)}catch(e){setPStatus(p,e.message,false)}}async function validateProvider(p){let key=$(p+'Key').value.trim(),model=p==='anthropic'?$('anthropicModel').value.trim():$(p+'Model').value;if(!key){setPStatus(p,'enter key first',false);return}if(!model){setPStatus(p,p==='anthropic'?'enter model first':'load models and choose one first',false);return}setPStatus(p,`validating ${model}…`);try{let ep=providerEndpoints(p),headers={'Content-Type':'application/json'},body;if(p==='anthropic'){headers['x-api-key']=key;headers['anthropic-version']='2023-06-01';body={model,max_tokens:8,messages:[{role:'user',content:'Reply OK'}]}}else{headers.Authorization=`Bearer ${key}`;body={model,messages:[{role:'user',content:'Reply OK'}],max_tokens:8}}let r=await fetch(ep.chat,{method:'POST',headers,body:JSON.stringify(body)}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let reg=aiRegistry(),providers=reg.providers||{},prev=providers[p]||{};providers[p]={...prev,key,model,verified:true,verifiedAt:new Date().toISOString()};reg={...reg,providers,defaultProvider:reg.defaultProvider||p};saveAIRegistry(reg);setPStatus(p,`registered · ${model}`,true);renderAIConfig()}catch(e){let reg=aiRegistry(),providers=reg.providers||{};providers[p]={...(providers[p]||{}),key,model,verified:false};saveAIRegistry({...reg,providers});setPStatus(p,e.message,false)}}$('veniceLoad').onclick=()=>loadProviderModels('venice');$('openrouterLoad').onclick=()=>loadProviderModels('openrouter');$('veniceValidate').onclick=()=>validateProvider('venice');$('openrouterValidate').onclick=()=>validateProvider('openrouter');$('anthropicValidate').onclick=()=>validateProvider('anthropic');$('defaultProvider').onchange=()=>{let r=aiRegistry();r.defaultProvider=$('defaultProvider').value;saveAIRegistry(r);renderAIConfig()};for(let p of ['venice','openrouter','anthropic']){$(p+'Key').addEventListener('input',()=>{let r=aiRegistry(),providers=r.providers||{},q=providers[p]||{};if(q.verified){providers[p]={...q,verified:false};saveAIRegistry({...r,providers});setPStatus(p,'changed · validate again',null)}})}$('anthropicModel').addEventListener('input',()=>{let r=aiRegistry(),providers=r.providers||{},q=providers.anthropic||{};if(q.verified){providers.anthropic={...q,verified:false};saveAIRegistry({...r,providers});setPStatus('anthropic','changed · validate again',null)}});async function callAI(msgs){let reg=aiRegistry(),p=reg.defaultProvider||'venice',c=(reg.providers||{})[p]||{};if(!c.verified||!c.key||!c.model)throw Error(`${providerName(p)} is not registered in Config`);let ep=providerEndpoints(p),headers={'Content-Type':'application/json'},body;if(p==='anthropic'){headers['x-api-key']=c.key;headers['anthropic-version']='2023-06-01';body={model:c.model,max_tokens:1600,messages:msgs.filter(x=>x.role!=='system'),system:msgs.find(x=>x.role==='system')?.content||''}}else{headers.Authorization=`Bearer ${c.key}`;body={model:c.model,messages:msgs,max_tokens:1600}}let r=await fetch(ep.chat,{method:'POST',headers,body:JSON.stringify(body)}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`AI HTTP ${r.status}`);return p==='anthropic'?x.content?.map(z=>z.text||'').join('\n'):x.choices?.[0]?.message?.content||''}
'''
s=prefix+replacement+suffix
s=s.replace("async function startAI(){let now=new Date().toISOString(),c=cfg(),a={id:'a-'+Date.now(),title:`${label(S.analysisRoot)} · ${S.h}`,status:'processing',createdAt:now,updatedAt:now,state:analysisState(),provider:c.provider,model:c.model,turns:[{role:'assistant',content:'Processing…',at:now,processing:true}]},all=analyses();", "async function startAI(){let now=new Date().toISOString(),reg=aiRegistry(),p=reg.defaultProvider||'venice',c=(reg.providers||{})[p]||{},a={id:'a-'+Date.now(),title:`${label(S.analysisRoot)} · ${S.h}`,status:'processing',createdAt:now,updatedAt:now,state:analysisState(),provider:p,model:c.model||'',turns:[{role:'assistant',content:'Processing…',at:now,processing:true}]},all=analyses();")
