s=s.replace("$('libTitle').textContent=`${a.title} · ${a.status}`;$('transcript').innerHTML=`<div class=\"turn\"><div class=\"who\">EVIDENCE</div><pre>${esc(JSON.stringify(a.state,null,2))}</pre></div>`+a.turns.map", "$('libTitle').textContent=`${a.title} · ${a.status} · ${providerName(a.provider||'venice')} ${a.model||''}`;$('transcript').innerHTML=`<div class=\"turn\"><div class=\"who\">EVIDENCE · ${esc(a.state.horizon)} · ${esc((a.state.series||[]).join(', '))}</div><div>${(a.state.evidence||[]).map(e=>{let c=e.catalog||{},h=e.health||{};return `<div class=\"rowMeta\">${esc(c.short_name||e.id)} · ${esc(c.native_cadence||'')} · ${esc(h.actualLatestCanonicalObservation||'—')} ${c.source_reference_url?`· <a href=\"${esc(c.source_reference_url)}\" target=\"_blank\" rel=\"noopener\">source</a>`:''}</div>`}).join('')}</div></div>`+a.turns.map")
